use reqwest::Client;

pub async fn fetch_pages(client: &Client, urls: &[String]) -> anyhow::Result<Vec<String>> {
    let mut bodies = Vec::with_capacity(urls.len());
    for url in urls {
        let body = client.get(url).send().await?.error_for_status()?.text().await?;
        bodies.push(body);
    }
    Ok(bodies)
}

