use crate::push::PushClient;

pub async fn notify_devices(client: &PushClient, tokens: Vec<String>, message: &str) -> usize {
    let mut delivered = 0;
    for token in tokens {
        if client.send(&token, message).await.is_ok() {
            delivered += 1;
        }
    }
    delivered
}

pub async fn complete_login(http: &reqwest::Client, code: &str, cfg: &OAuthConfig) -> anyhow::Result<Account> {
    let token: TokenResponse = http
        .post(&cfg.token_url)
        .form(&[("code", code), ("client_id", &cfg.client_id)])
        .send()
        .await?
        .json()
        .await?;
    let profile: Profile = http.get(&cfg.userinfo_url).bearer_auth(&token.access_token).send().await?.json().await?;
    Ok(Account { token, profile })
}

