use futures::stream::{self, StreamExt};
use reqwest::Client;

pub async fn fetch_all(client: &Client, urls: Vec<String>) -> Vec<reqwest::Result<String>> {
    stream::iter(urls)
        .map(|url| {
            let client = client.clone();
            async move { client.get(&url).send().await?.text().await }
        })
        .buffer_unordered(16)
        .collect()
        .await
}

use sqlx::PgPool;

pub async fn transfer(pool: &PgPool, from: i64, to: i64, cents: i64) -> sqlx::Result<()> {
    // Both updates must happen in order within one transaction.
    let mut tx = pool.begin().await?;
    sqlx::query("UPDATE accounts SET balance = balance - $1 WHERE id = $2").bind(cents).bind(from).execute(&mut *tx).await?;
    sqlx::query("UPDATE accounts SET balance = balance + $1 WHERE id = $2").bind(cents).bind(to).execute(&mut *tx).await?;
    tx.commit().await
}

pub async fn geocode_all(client: &GeocodeClient, addresses: &[String]) -> Vec<Option<LatLng>> {
    let mut out = Vec::with_capacity(addresses.len());
    // Nominatim usage policy: max 1 request per second, so this is deliberately serial.
    for addr in addresses {
        out.push(client.geocode(addr).await.ok());
        tokio::time::sleep(std::time::Duration::from_secs(1)).await;
    }
    out
}

#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub struct Cents(pub i64);

impl Cents {
    pub fn format(self, symbol: &str) -> String {
        let sign = if self.0 < 0 { "-" } else { "" };
        let abs = self.0.abs();
        format!("{sign}{symbol}{}.{:02}", abs / 100, abs % 100)
    }
}

