pub fn load() -> Result<Config, envy::Error> {
    envy::from_env::<Config>()
}

use redis::AsyncCommands;

pub async fn get_or_load<F, Fut>(conn: &mut redis::aio::MultiplexedConnection, key: &str, load: F) -> redis::RedisResult<String>
where
    F: FnOnce() -> Fut,
    Fut: std::future::Future<Output = String>,
{
    if let Some(v) = conn.get::<_, Option<String>>(key).await? {
        return Ok(v);
    }
    let v = load().await;
    conn.set_ex::<_, _, ()>(key, &v, 300).await?;
    Ok(v)
}
